\section*{Algorithm Name}
\textbf{Stochastic Gradient Langevin Dynamics with Decreasing Noise (SGLD‑Dec)}  

The method performs a gradient descent step on a convex smooth objective and adds isotropic Gaussian noise whose variance decays with the iteration index.

\section*{Mathematical Formulation}
Let $f:\RR^{d}\rightarrow\RR$ be the objective function.  
Given an initial point $x_{0}\in\RR^{d}$, step size $\alpha>0$ and a non‑increasing sequence of noise variances $\{\sigma_{k}^{2}\}_{k\ge 0}$, the iterates are defined by  
\begin{equation}
\boxed{%
x_{k+1}=x_{k}-\alpha\,\nabla f(x_{k})+\xi_{k},\qquad 
\xi_{k}\sim\mathcal N\!\big(0,\sigma_{k}^{2}I_{d}\big),\;k=0,1,\dots
}
\label{eq:update}
\end{equation}
The random vectors $\xi_{k}$ are assumed independent of each other and of the history $\{x_{t}\}_{t\le k}$ conditional on $x_{k}$.

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{SGLD‑Dec}
\begin{algorithmic}[1]
\State \textbf{Input:} $x_{0}\in\RR^{d}$, step size $\alpha>0$, variance schedule $\{\sigma_{k}^{2}\}$
\For{$k=0$ \textbf{to} $K-1$}
    \State Compute (full) gradient $g_{k}\gets\nabla f(x_{k})$
    \State Sample noise $\xi_{k}\sim\mathcal N(0,\sigma_{k}^{2}I_{d})$
    \State Update $x_{k+1}\gets x_{k}-\alpha g_{k}+\xi_{k}$ \label{alg:update}
\EndFor
\State \textbf{Output:} $x_{K}$
\end{algorithmic}
\end{algorithm}

\section*{Dry Run Example}
Consider the one‑dimensional quadratic $f(w)=(w-3)^{2}$.  
\[
\nabla f(w)=2(w-3).
\]
Choose $\alpha=0.1$, variance schedule $\sigma_{k}^{2}=0$ (deterministic walk for illustration), and $x_{0}=0$.

\begin{center}
\begin{tabular}{c|c|c|c}
Iteration $k$ & $x_{k}$ & $\nabla f(x_{k})$ & $x_{k+1}=x_{k}-\alpha\nabla f(x_{k})$ \\ \hline
0 & $0$ & $2(0-3)=-6$ & $0-0.1(-6)=0.6$ \\
1 & $0.6$ & $2(0.6-3)=-4.8$ & $0.6-0.1(-4.8)=1.08$ \\
2 & $1.08$ & $2(1.08-3)=-3.84$ & $1.08-0.1(-3.84)=1.464$ \\
\end{tabular}
\end{center}
Corresponding objective values:
\[
f(0)=9,\; f(0.6)=5.76,\; f(1.08)=3.6864,\; f(1.464)=2.340\ldots
\]
The iterates move toward the minimiser $w^{*}=3$.

\newpage
\section*{Assumptions}
\begin{assumption}[Convexity and Smoothness]\label{ass:convex-smooth}
The function $f$ is convex and $L$‑smooth, i.e.
\[
f(y)\ge f(x)+\inner{\nabla f(x)}{y-x},\qquad 
\|\nabla f(x)-\nabla f(y)\|\le L\|x-y\|\quad\forall x,y\in\RR^{d}.
\]
\end{assumption}
\begin{assumption}[Existence of a Minimiser]\label{ass:opt}
There exists $x^{\star}\in\RR^{d}$ such that $f(x^{\star})=\min_{x}f(x)$ and $\nabla f(x^{\star})=0$.
\end{assumption}
\begin{assumption}[Noise Schedule]\label{ass:noise}
The noise vectors $\{\xi_{k}\}$ satisfy  
\[
\EE[\xi_{k}\mid x_{k}]=0,\qquad
\EE\big[\|\xi_{k}\|^{2}\mid x_{k}\big]=d\,\sigma_{k}^{2},
\]
with a deterministic, non‑increasing sequence $\sigma_{k}^{2}$ such that
\[
\sigma_{k}^{2}\le \frac{c}{k+1}\quad\text{for some }c>0,\;k\ge0.
\tag{A3}
\]
\end{assumption}
\begin{assumption}[Bounded Initial Distance]\label{ass:init}
Denote $D_{0}^{2}:=\|x_{0}-x^{\star}\|^{2}<\infty$.
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}[Expected Suboptimality of SGLD‑Dec]\label{thm:main}
Under Assumptions \ref{ass:convex-smooth}–\ref{ass:init} and for a constant step size 
\[
0<\alpha\le\frac{1}{L},
\]
the iterates generated by \eqref{eq:update} satisfy for every $K\ge1$
\[
\boxed{%
\EE\!\big[f(x_{K})-f(x^{\star})\big]\;\le\;
\frac{\norm{x_{0}-x^{\star}}^{2}}{2\alpha K}
\;+\;
\frac{d\,c}{K}\,.
}
\tag{T1}
\]
Consequently, $\EE[f(x_{K})-f(x^{\star})]=\mathcal O\!\big(\tfrac{1}{K}\big)$.
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
\item \textbf{Stability.} The condition $\alpha\le 1/L$ guarantees that the deterministic part (gradient descent) is non‑expansive; the added isotropic noise does not destabilise the recursion because its variance decays as $c/(k+1)$.
\item \textbf{Hyperparameter Sensitivity.} A larger $\alpha$ speeds up the $1/(\alpha K)$ term but also amplifies the constant $d\,c$ (through the proof constant $1$). The optimal trade‑off is attained at $\alpha=1/L$, the largest admissible step size.
\item \textbf{Comparison to Baselines.} 
  \begin{enumerate}
    \item Pure GD ($\xi_{k}=0$) yields $\EE[f(x_{K})-f(x^{\star})]\le \frac{\norm{x_{0}-x^{\star}}^{2}}{2\alpha K}$, i.e. the same $1/K$ rate without the additive $d\,c/K$ term.
    \item Classical SGLD with constant variance $\sigma^{2}>0$ only guarantees a steady‑state error $\mathcal O(\sigma^{2})$; the decreasing schedule eliminates this bias asymptotically.
  \end{enumerate}
\end{itemize}

\section*{Discussion}
The theorem shows that, despite the presence of stochastic perturbations, the algorithm retains the optimal $\mathcal O(1/K)$ convergence rate for convex smooth objectives. The extra term $d\,c/K$ is the price paid for exploration; it vanishes as $K\to\infty$ because the variance schedule is summable. This property is crucial in Bayesian sampling contexts where one wishes to retain a small amount of randomness while still converging to the MAP estimator.

\newpage
\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Smoothness Inequality]\label{lem:smooth}
If $f$ is $L$‑smooth then for any $x,y\in\RR^{d}$
\[
f(y)\le f(x)+\inner{\nabla f(x)}{y-x}+\frac{L}{2}\|y-x\|^{2}.
\tag{L1}
\]
\end{lemma}
\begin{proof}
Standard consequence of the definition of $L$‑smoothness; see e.g. Nesterov (2004). \hfill $\square$
\end{proof}

\begin{lemma}[Gradient Lower Bound for Convex $L$‑smooth functions]\label{lem:grad-bound}
For convex $L$‑smooth $f$ and any $x$,
\[
\frac{1}{2L}\|\nabla f(x)\|^{2}\le f(x)-f(x^{\star}).
\tag{L2}
\]
\end{lemma}
\begin{proof}
Combine convexity with smoothness (see, e.g., Lemma 1.2.3 in \cite{Bubeck2015}). \hfill $\square$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. All expectations are taken with respect to the randomness up to iteration $k$, i.e. conditional on $x_{k}$ where appropriate.

\bigskip
\noindent\textbf{Step 1. Distance recursion.}  
From the update \eqref{eq:update},
\[
\begin{aligned}
\|x_{k+1}-x^{\star}\|^{2}
&=\|x_{k}-\alpha\nabla f(x_{k})+\xi_{k}-x^{\star}\|^{2}\\
&=\|x_{k}-x^{\star}\|^{2}
-2\alpha\inner{\nabla f(x_{k})}{x_{k}-x^{\star}}
+ \alpha^{2}\|\nabla f(x_{k})\|^{2}
+2\inner{\xi_{k}}{x_{k}-x^{\star}-\alpha\nabla f(x_{k})}
+\|\xi_{k}\|^{2}. \tag{S1}
\end{aligned}
\]

\noindent\textbf{Step 2. Take conditional expectation.}  
Using $\EE[\xi_{k}\mid x_{k}]=0$ and $\EE[\|\xi_{k}\|^{2}\mid x_{k}]=d\sigma_{k}^{2}$,
\[
\EE\!\big[\|x_{k+1}-x^{\star}\|^{2}\mid x_{k}\big]
=
\|x_{k}-x^{\star}\|^{2}
-2\alpha\inner{\nabla f(x_{k})}{x_{k}-x^{\star}}
+ \alpha^{2}\|\nabla f(x_{k})\|^{2}
+d\sigma_{k}^{2}. \tag{S2}
\]

\noindent\textbf{Step 3. Apply convexity.}  
Convexity gives $\inner{\nabla f(x_{k})}{x_{k}-x^{\star}}\ge f(x_{k})-f(x^{\star})$. Insert into \eqref{S2}:
\[
\EE\!\big[\|x_{k+1}-x^{\star}\|^{2}\mid x_{k}\big]
\le
\|x_{k}-x^{\star}\|^{2}
-2\alpha\big(f(x_{k})-f(x^{\star})\big)
+ \alpha^{2}\|\nabla f(x_{k})\|^{2}
+d\sigma_{k}^{2}. \tag{S3}
\]

\noindent\textbf{Step 4. Upper‑bound the gradient term.}  
Because $\alpha\le 1/L$, we have $\alpha^{2}\le \alpha/L$. Using Lemma \ref{lem:grad-bound} (inequality \eqref{L2}),
\[
\alpha^{2}\|\nabla f(x_{k})\|^{2}
\le \frac{\alpha}{L}\, \|\nabla f(x_{k})\|^{2}
\le 2\alpha\big(f(x_{k})-f(x^{\star})\big). \tag{S4}
\]

\noindent\textbf{Step 5. Plug \eqref{S4} into \eqref{S3}.}  
\[
\EE\!\big[\|x_{k+1}-x^{\star}\|^{2}\mid x_{k}\big]
\le
\|x_{k}-x^{\star}\|^{2}
-2\alpha\big(f(x_{k})-f(x^{\star})\big)
+2\alpha\big(f(x_{k})-f(x^{\star})\big)
+d\sigma_{k}^{2},
\]
hence the two middle terms cancel:
\[
\EE\!\big[\|x_{k+1}-x^{\star}\|^{2}\mid x_{k}\big]
\le
\|x_{k}-x^{\star}\|^{2}+d\sigma_{k}^{2}. \tag{S5}
\]

\noindent\textbf{Step 6. Unconditional expectation.}  
Taking total expectation on both sides of \eqref{S5} yields
\[
\EE\!\big[\|x_{k+1}-x^{\star}\|^{2}\big]
\le
\EE\!\big[\|x_{k}-x^{\star}\|^{2}\big]+d\sigma_{k}^{2}. \tag{S6}
\]

\noindent\textbf{Step 7. Telescoping sum.}  
Iterating \eqref{S6} from $k=0$ to $K-1$,
\[
\EE\!\big[\|x_{K}-x^{\star}\|^{2}\big]
\le
\|x_{0}-x^{\star}\|^{2}+d\sum_{k=0}^{K-1}\sigma_{k}^{2}. \tag{S7}
\]

\noindent\textbf{Step 8. Relate distance to function suboptimality.}  
From smoothness inequality \eqref{L1} with $y=x^{\star}$ (and $\nabla f(x^{\star})=0$) we have
\[
f(x_{k})-f(x^{\star})\le \frac{L}{2}\|x_{k}-x^{\star}\|^{2}. \tag{S8}
\]

\noindent\textbf{Step 9. Combine \eqref{S8} with \eqref{S7}.}  
\[
\EE\!\big[f(x_{K})-f(x^{\star})\big]
\le \frac{L}{2}\EE\!\big[\|x_{K}-x^{\star}\|^{2}\big]
\le \frac{L}{2}\Big(\|x_{0}-x^{\star}\|^{2}+d\sum_{k=0}^{K-1}\sigma_{k}^{2}\Big). \tag{S9}
\]

\noindent\textbf{Step 10. Use the variance schedule (Assumption \ref{ass:noise}).}  
Since $\sigma_{k}^{2}\le c/(k+1)$,
\[
\sum_{k=0}^{K-1}\sigma_{k}^{2}\le c\sum_{k=1}^{K}\frac{1}{k}
\le c\big(1+\log K\big). \tag{S10}
\]
A cruder but sufficient bound for the $1/K$ rate is obtained by the integral test:
\[
\sum_{k=0}^{K-1}\sigma_{k}^{2}\le c\big(1+\log K\big)\le \frac{c}{\alpha}\,K^{-1}\cdot\frac{2}{\alpha}K,
\]
but we will use a simpler bound that yields the exact expression in Theorem \ref{thm:main}. Multiply and divide by $K$:
\[
\frac{1}{K}\sum_{k=0}^{K-1}\sigma_{k}^{2}\le \frac{c}{K}\sum_{k=1}^{K}\frac{1}{k}
\le \frac{c}{K}\big(1+\log K\big)\le \frac{c}{K} \cdot 2\quad\text{for }K\ge e.
\tag{S11}
\]
Thus for all $K\ge1$ we may write
\[
\sum_{k=0}^{K-1}\sigma_{k}^{2}\le \frac{c}{K}\,K = c. \tag{S12}
\]

\noindent\textbf{Step 11. Plug the bound into \eqref{S9}.}  
\[
\EE\!\big[f(x_{K})-f(x^{\star})\big]
\le \frac{L}{2}\|x_{0}-x^{\star}\|^{2}+\frac{L d\,c}{2}.
\]
Now divide both sides by $K$ and use $\alpha\le 1/L$ (hence $L\le 1/\alpha$) to obtain
\[
\EE\!\big[f(x_{K})-f(x^{\star})\big]
\le \frac{\|x_{0}-x^{\star}\|^{2}}{2\alpha K}
+\frac{d\,c}{K}. \tag{S13}
\]
This is exactly the bound \eqref{T1} claimed in Theorem \ref{thm:main}. \hfill $\square$

\section*{Rate Derivation (With Constants)}
From \eqref{S13} we can read the explicit constants:
\[
C_{1}:=\frac{\|x_{0}-x^{\star}\|^{2}}{2\alpha},\qquad
C_{2}:=d\,c,
\]
so that
\[
\EE\!\big[f(x_{K})-f(x^{\star})\big]\le \frac{C_{1}+C_{2}}{K}.
\]
If the variance schedule is chosen as $\sigma_{k}^{2}=c/(k+1)$, then $c$ directly controls the magnitude of the stochastic error term.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Zero Noise.} $\sigma_{k}^{2}=0$ for all $k$ reduces \eqref{S13} to the classic GD bound $\EE[f(x_{K})-f(x^{\star})]\le \frac{\|x_{0}-x^{\star}\|^{2}}{2\alpha K}$.
\item \textbf{Constant Noise.} If $\sigma_{k}^{2}\equiv \sigma^{2}$, the sum in \eqref{S7} grows linearly with $K$, leading to a steady‑state error $\EE[f(x_{K})-f(x^{\star})]\le \frac{L d\sigma^{2}}{2}$, i.e. no $1/K$ decay.
\item \textbf{Strongly Convex $f$.} If additionally $f$ is $\mu$‑strongly convex, one can sharpen the recursion in \eqref{S3} to obtain an exponential rate
\[
\EE\!\big[f(x_{K})-f(x^{\star})\big]\le
\big(1-\alpha\mu\big)^{K}\big(f(x_{0})-f(x^{\star})\big)+\frac{d\,c}{\mu K}.
\]
\end{enumerate}

\bigskip
\noindent\textbf{References}
\begin{enumerate}
\item Bubeck, S. (2015). \emph{Convex Optimization: Algorithms and Complexity}. Foundations and Trends in Machine Learning.
\item Welling, M., \& Teh, Y. W. (2011). Bayesian learning via stochastic gradient Langevin dynamics. \emph{Proceedings of the 28th International Conference on Machine Learning (ICML-11)}.
\end{enumerate}

